#include "../src/learning/memory_system.h"
#include "../src/learning/learning_controller.h"
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <sys/resource.h>
namespace {
struct R{double accuracy=0,restart_accuracy=0;uint64_t processed=0,episodes=0,replay_events=0,bound=0;bool restart=false;long peak_kb=0;};
int target(int task,int ctx){return task==0?ctx:1-ctx;} int pick(const genesis::SynapseBlock&s,size_t b){return s.weights[b]>=s.weights[b+1]?0:1;}
void learn(genesis::LearningController&l,genesis::SynapseBlock&s,genesis::NeuronBlock&n,size_t b,int a,float reward,uint64_t t){size_t id=b+(size_t)a;l.on_pre_spike((uint32_t)id,s,t);l.on_post_spike((uint32_t)(id+1),s,t+1);genesis::LearningSignal q;q.reward=reward;q.tick=t+1;l.apply_modulation(q);l.update(s,n,t+1);l.reset_traces(s);}
long rss(){struct rusage u{};getrusage(RUSAGE_SELF,&u);return u.ru_maxrss;}
}
int main(int ac,char**av){uint64_t seed=ac>1?std::stoull(av[1]):424242;std::filesystem::path d=ac>2?av[2]:"artifacts/large-workload";std::filesystem::create_directories(d);genesis::LearningConfig c;c.eta=.04f;c.trace_decay=.97f;c.a_plus=.5f;c.a_minus=.1f;c.reward_coefficient=1;c.prediction_error_coefficient=0;c.novelty_coefficient=0;c.task_relevance_coefficient=0;c.executive_permission_coefficient=0;c.homeostasis_enabled=false;c.structural_enabled=false;c.weight_min=.01f;c.weight_max=1;genesis::NeuronBlock n;n.resize(9);for(float&x:n.plasticity_scale)x=1;genesis::SynapseBlock s;s.resize(8);s.weights.assign(8,.5f);s.precision_scale.assign(8,1);s.pre_indices.assign(8,0);s.post_indices.resize(8);for(size_t i=0;i<8;++i)s.post_indices[i]=(uint32_t)(i+1);genesis::LearningController l(c);l.initialize(9,8);genesis::MemoryConfig mc;mc.replay_quota_per_context=100;mc.max_replay_events=1000000;genesis::MemorySystem mem(seed,mc);mem.initialize_arena(9,8);uint64_t tick=1;uint64_t replay_events=0;constexpr uint64_t total=100000;
 mem.set_replay_callback([&](const genesis::MemoryEvent&e,genesis::ReplayMode){size_t slot=(size_t)(e.header.payload_id%4);int a=pick(s,slot*2);learn(l,s,n,slot*2,a,a==target((int)(slot/2),(int)(slot%2))?1:-1,tick++);++replay_events;});
 for(uint64_t ep=0;ep<total;++ep){int task=(int)(ep%2),ctx=(int)((ep/2)%2),a=pick(s,(size_t)(task*2+ctx)*2);if((ep%100)<20)a=(int)((ep+seed)%2);size_t slot=(size_t)(task*2+ctx);uint64_t t=tick;learn(l,s,n,slot*2,a,a==target(task,ctx)?1:-1,t);genesis::EventHeader h{ep+1,t,1,100,(uint64_t)slot,seed};auto id=mem.begin_episode(h);genesis::EventHeader ah{ep+1,t+1,1,(uint32_t)(200+a),(uint64_t)a,seed};mem.append_event(id,ah);mem.set_active_metrics(.3f,0,0,a==target(task,ctx)?1:-1);mem.close_episode(id,a==target(task,ctx)?1:-1);tick+=3;if(ep%10000==9999){auto selected=mem.select_replay({0,0,tick},8);mem.replay(selected,genesis::ReplayMode::ExactEvent,1000);} }
 auto eval=[&](const genesis::SynapseBlock&x){size_t good=0;for(int task=0;task<2;++task)for(int ctx=0;ctx<2;++ctx)for(size_t i=0;i<250;++i)good+=pick(x,(size_t)(task*2+ctx)*2)==target(task,ctx)?1:0;return(double)good/1000;};R r;r.processed=total;r.episodes=mem.episodes().size();r.accuracy=eval(s);r.replay_events=replay_events;r.bound=l.metrics().bound_violations;r.peak_kb=rss();{std::ofstream w(d/"weights.state");for(float x:s.weights)w<<std::setprecision(10)<<x<<'\n';}genesis::SynapseBlock restored;restored.resize(8);restored.weights.assign(8,0);{std::ifstream w(d/"weights.state");for(float&x:restored.weights)w>>x;}r.restart_accuracy=eval(restored);r.restart=restored.weights==s.weights;mem.save(d/"memory.bin");std::ofstream o(d/"summary.txt");bool pass=r.processed>=total&&r.accuracy>=.8&&r.restart_accuracy>=.8&&r.replay_events>0&&r.restart&&r.bound==0;o<<"B4_LARGE_WORKLOAD="<<(pass?"PASS":"FAIL")<<'\n'<<"processed_episodes="<<r.processed<<'\n'<<"captured_memory_episodes="<<r.episodes<<'\n'<<"accuracy="<<r.accuracy<<'\n'<<"restart_accuracy="<<r.restart_accuracy<<'\n'<<"replay_events="<<r.replay_events<<'\n'<<"memory_episodes="<<mem.episodes().size()<<'\n'<<"peak_rss_kb="<<r.peak_kb<<'\n'<<"restart_match="<<(r.restart?1:0)<<'\n'<<"bound_violations="<<r.bound<<'\n';std::cout<<"B4_LARGE_WORKLOAD="<<(pass?"PASS":"FAIL")<<'\n'<<std::fixed<<std::setprecision(4)<<"episodes="<<r.episodes<<" accuracy="<<r.accuracy<<" restart="<<r.restart_accuracy<<" replay="<<r.replay_events<<" peak_rss_kb="<<r.peak_kb<<'\n';return pass?0:1;}
